1	import { useState } from 'react';
2	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
3	import {
4	  clientsKey,
5	  createProject,
6	  listClientOptions,
7	  projectsKey,
8	  projectStatuses,
9	  type ProjectStatus,
10	} from './api';
11	
12	// Add a project for a client. The fields the user is typing live in useState (uncommitted input);
13	// the saved data lives on the server. The client select is populated from the ['clients'] query —
14	// each option's value is the client id — so the user picks which client the project is for. On
15	// success we invalidate ['projects'] so the list refetches — we never hand-maintain the list.
16	export function ProjectForm() {
17	  const queryClient = useQueryClient();
18	  const { data: clients } = useQuery({ queryKey: clientsKey, queryFn: listClientOptions });
19	  const [name, setName] = useState('');
20	  const [clientId, setClientId] = useState('');
21	  // The lifecycle the new project starts in — uncommitted input like name/client, so it lives in
22	  // useState until submit. Defaults to ACTIVE, the state a fresh project gets.
23	  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
24	
25	  const mutation = useMutation({
26	    mutationFn: createProject,
27	    onSuccess: () => {
28	      setName('');
29	      setClientId('');
30	      setStatus('ACTIVE');
31	      void queryClient.invalidateQueries({ queryKey: projectsKey });
32	    },
33	  });
34	
35	  const submit = (e: React.FormEvent) => {
36	    e.preventDefault();
37	    if (name.trim() === '' || clientId === '') {
38	      return;
39	    }
40	    mutation.mutate({ name: name.trim(), clientId: Number(clientId), status });
41	  };
42	
43	  return (
44	    <form onSubmit={submit}>
45	      <input
46	        data-testid="project-form-name"
47	        placeholder="Name"
48	        value={name}
49	        onChange={(e) => setName(e.target.value)}
50	      />
