3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // invoices references projects references clients, so H2 refuses to TRUNCATE a parent while
36	        // the FK exists — drop referential integrity for the duration, truncate all, then restore.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        try {
39	            jdbc.execute("TRUNCATE TABLE dashboard_reference");
40	            jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
41	            jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
42	            jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
43	            jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
44	            jdbc.execute("TRUNCATE TABLE invoice_payments RESTART IDENTITY");
45	            jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
46	            jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
47	            jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
48	            jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
49	            jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
50	        } finally {
51	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
52	        }
53	    }
54	
55	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
56	    @PostMapping("/seed")
57	    @SuppressWarnings("unchecked")
58	    public void seed(@RequestBody Map<String, Object> fixture) {
59	        // The reference date the dashboard measures "overdue" against (single row, id = 1). Optional:
60	        // a spec that does not care leaves it out, so the dashboard falls back to today.
61	        Object asOf = fixture.get("asOf");
62	        if (asOf != null) {
63	            jdbc.update("INSERT INTO dashboard_reference (id, as_of) VALUES (1, ?)",
64	                    java.sql.Date.valueOf(java.time.LocalDate.parse(asOf.toString())));
65	        }
66	        List<Map<String, Object>> clients =
67	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
68	        // Explicit ids from the fixture (the spec asserts rows by these ids), via JdbcTemplate.
69	        for (Map<String, Object> c : clients) {
70	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
71	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
72	        }
73	        List<Map<String, Object>> projects =
74	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
75	        for (Map<String, Object> p : projects) {
76	            // status is optional in the fixture — a spec that only cares a project exists leaves it
77	            // out, defaulting to ACTIVE (the same state a fresh project gets, V22__project_status.sql).
78	            Object status = p.getOrDefault("status", "ACTIVE");
79	            // archived is optional too — a spec that only cares a project exists leaves it out,
80	            // defaulting to not-archived (the same state a fresh project gets, V16__project_archived.sql).
81	            boolean archived = Boolean.TRUE.equals(p.getOrDefault("archived", Boolean.FALSE));
82	            // budget is optional in the fixture — a spec that does not care about the budget leaves
83	            // it out, so the column stays NULL (the same state a fresh project gets until one is set,
84	            // V23__project_budget.sql).
85	            java.math.BigDecimal budget = p.get("budget") != null
86	                    ? new java.math.BigDecimal(p.get("budget").toString())
87	                    : null;
88	            jdbc.update(
89	                    "INSERT INTO projects (id, name, client_id, status, archived, budget)"
90	                            + " VALUES (?, ?, ?, ?, ?, ?)",
91	                    ((Number) p.get("id")).longValue(), p.get("name"),
92	                    ((Number) p.get("clientId")).longValue(), status.toString(), archived, budget);
93	        }
94	        List<Map<String, Object>> contacts =
95	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
96	        for (Map<String, Object> c : contacts) {
97	            // primary is optional in the fixture — a spec that does not care leaves it out, so the
98	            // contact defaults to not-primary (the same state a fresh contact gets, V26__contact_primary.sql).
99	            boolean primary = Boolean.TRUE.equals(c.getOrDefault("primary", Boolean.FALSE));
100	            jdbc.update(
101	                    "INSERT INTO contacts (id, name, email, contact_role, client_id, is_primary)"
102	                            + " VALUES (?, ?, ?, ?, ?, ?)",
103	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"),
104	                    c.get("role"), ((Number) c.get("clientId")).longValue(), primary);
105	        }
106	        List<Map<String, Object>> invoices =
107	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
108	        for (Map<String, Object> inv : invoices) {
109	            Object status = inv.getOrDefault("status", "DRAFT");
110	            // Dates are optional in the fixture — a spec that only cares about the lifecycle leaves
111	            // them out, so default issued=today / due=+30 days (the same rule CreateInvoice applies).
112	            java.time.LocalDate issued = inv.get("issuedDate") != null
113	                    ? java.time.LocalDate.parse(inv.get("issuedDate").toString())
114	                    : java.time.LocalDate.now();
115	            java.time.LocalDate due = inv.get("dueDate") != null
116	                    ? java.time.LocalDate.parse(inv.get("dueDate").toString())
117	                    : issued.plusDays(30);
118	            // An invoice is built from line items; its amount is the sum of each line's qty times
119	            // unit price. A fixture gives the lines (not a figure), so compute the amount from them
120	            // here — the same derivation CreateLineItem keeps in step on every add. A legacy fixture
121	            // that still supplies an explicit amount (and no lines) is honoured as-is.
122	            List<Map<String, Object>> lineItems =
123	                    (List<Map<String, Object>>) inv.getOrDefault("lineItems", List.of());
124	            java.math.BigDecimal amount;
125	            if (inv.get("amount") != null) {
126	                amount = new java.math.BigDecimal(inv.get("amount").toString());
127	            } else {
128	                amount = java.math.BigDecimal.ZERO;
129	                for (Map<String, Object> li : lineItems) {
130	                    amount = amount.add(new java.math.BigDecimal(li.get("unitPrice").toString())
131	                            .multiply(new java.math.BigDecimal(li.get("qty").toString())));
132	                }
133	            }
134	            // discountPct is optional in the fixture — a spec that does not care about a discount
135	            // leaves it out, defaulting to 0 (the same state a fresh invoice gets until one is set,
136	            // V29__invoice_discount.sql), so the final total equals the subtotal.
137	            java.math.BigDecimal discountPct = inv.get("discountPct") != null
138	                    ? new java.math.BigDecimal(inv.get("discountPct").toString())
139	                    : java.math.BigDecimal.ZERO;
140	            // taxPct is optional in the fixture — a spec that does not care about tax leaves it out,
141	            // defaulting to 0 (the same state a fresh invoice gets until one is set,
142	            // V30__invoice_tax.sql), so the final total adds nothing on top of the discounted amount.
143	            java.math.BigDecimal taxPct = inv.get("taxPct") != null
144	                    ? new java.math.BigDecimal(inv.get("taxPct").toString())
145	                    : java.math.BigDecimal.ZERO;
146	            jdbc.update(
147	                    "INSERT INTO invoices"
148	                            + " (id, project_id, amount, status, issued_date, due_date, discount_pct, tax_pct)"
149	                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
150	                    ((Number) inv.get("id")).longValue(),
151	                    ((Number) inv.get("projectId")).longValue(),
152	                    amount,
153	                    status.toString(),
154	                    java.sql.Date.valueOf(issued),
155	                    java.sql.Date.valueOf(due),
156	                    discountPct,
157	                    taxPct);
158	            // Insert the invoice's lines with their explicit fixture ids (the spec asserts rows by
159	            // these ids), owned by this invoice.
160	            for (Map<String, Object> li : lineItems) {
161	                // unit is optional in the fixture — a spec that does not care leaves it out, so the
162	                // line defaults to a neutral "units" (the same fallback CreateLineItem applies).
163	                Object unit = li.getOrDefault("unit", "units");
164	                jdbc.update(
165	                        "INSERT INTO invoice_line_items"
166	                                + " (id, invoice_id, description, quantity, unit, unit_price)"
167	                                + " VALUES (?, ?, ?, ?, ?, ?)",
168	                        ((Number) li.get("id")).longValue(),
169	                        ((Number) inv.get("id")).longValue(),
170	                        li.get("description"),
171	                        ((Number) li.get("qty")).intValue(),
172	                        unit.toString(),
173	                        new java.math.BigDecimal(li.get("unitPrice").toString()));
174	            }
175	        }
176	        // Payments a client has made against an invoice (amount + the date paid), with their
177	        // explicit fixture ids (the spec asserts rows by these ids), owned by a seeded invoice.
178	        List<Map<String, Object>> payments =
179	                (List<Map<String, Object>>) fixture.getOrDefault("payments", List.of());
180	        long maxPaymentId = 0;
181	        for (Map<String, Object> pay : payments) {
182	            long paymentId = ((Number) pay.get("id")).longValue();
183	            jdbc.update(
184	                    "INSERT INTO invoice_payments (id, invoice_id, amount, paid_date)"
185	                            + " VALUES (?, ?, ?, ?)",
186	                    paymentId,
187	                    ((Number) pay.get("invoiceId")).longValue(),
188	                    new java.math.BigDecimal(pay.get("amount").toString()),
189	                    java.sql.Date.valueOf(
190	                            java.time.LocalDate.parse(pay.get("date").toString())));
191	            maxPaymentId = Math.max(maxPaymentId, paymentId);
192	        }
193	        // Explicit ids (GENERATED BY DEFAULT) do NOT advance H2's identity sequence, so a payment
194	        // recorded through the API would collide on id 1. Bump the sequence past the seeded rows.
195	        if (maxPaymentId > 0) {
196	            jdbc.execute(
197	                    "ALTER TABLE invoice_payments ALTER COLUMN id RESTART WITH " + (maxPaymentId + 1));
198	        }
199	        List<Map<String, Object>> tasks =
200	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
201	        for (Map<String, Object> t : tasks) {
202	            // done is optional in the fixture — a spec that only cares a task exists leaves it out,
203	            // so it defaults to not-done (the same state CreateTask would give a fresh task).
204	            boolean done = Boolean.TRUE.equals(t.getOrDefault("done", Boolean.FALSE));
205	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
206	                    ((Number) t.get("id")).longValue(),
207	                    ((Number) t.get("projectId")).longValue(),
208	                    t.get("title"), done);
209	        }
210	        List<Map<String, Object>> tags =
211	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
212	        for (Map<String, Object> tag : tags) {
213	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)",
214	                    ((Number) tag.get("id")).longValue(), tag.get("name"));
215	        }
216	        // Notes are written against a generic target (type + id); the fixture pins each note's
217	        // write time so the newest-first order is deterministic. `at` is optional — a spec that
218	        // only cares a note exists leaves it out, defaulting to now().
219	        List<Map<String, Object>> notes =
220	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
221	        long maxNoteId = 0;
222	        for (Map<String, Object> n : notes) {
223	            java.time.OffsetDateTime at = n.get("at") != null
224	                    ? java.time.OffsetDateTime.parse(n.get("at").toString())
225	                    : java.time.OffsetDateTime.now();
226	            long noteId = ((Number) n.get("id")).longValue();
227	            jdbc.update(
228	                    "INSERT INTO notes (id, target_type, target_id, text, created_at)"
229	                            + " VALUES (?, ?, ?, ?, ?)",
230	                    noteId,
231	                    n.get("targetType"),
232	                    ((Number) n.get("targetId")).longValue(),
233	                    n.get("text"),
234	                    at);
235	            maxNoteId = Math.max(maxNoteId, noteId);
236	        }
237	        // Explicit ids (GENERATED BY DEFAULT) do NOT advance H2's identity sequence, so the app's
238	        // next create would collide on id 1. Bump the sequence past the seeded rows so a note added
239	        // through the API gets a fresh id above them.
240	        if (maxNoteId > 0) {
241	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
242	        }
243	        // The many-to-many links: which seeded tag sits on which seeded project.
244	        List<Map<String, Object>> projectTags =
245	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
246	        for (Map<String, Object> pt : projectTags) {
247	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
248	                    ((Number) pt.get("projectId")).longValue(),
249	                    ((Number) pt.get("tagId")).longValue());
250	        }
251	    }
252	}
