  const project = projects?.find((p: Project) => p.id === projectId);

  if (!project) {
    return null;
  }

  return <span data-testid="project-code">{project.code}</span>;
}

export const contribution = ProjectRow.fill({ order: -5, Component: ProjectCodeCell });

